function calculate(ctx, fuelVolumeL) {

    var values = fuelVolumeL.values;

    if (values == null || values.size() < 2) {
        return null;
    }

    var first = values.get(0).value;
    var last = values.get(values.size() - 1).value;

    if (first == null || last == null) {
        return null;
    }

    var fuelDrop = first - last;

    if (fuelDrop <= 0) {
        fuelDrop = 0;
    }

    return {
        "ts": ctx.latestTs,
        "values": {
            "fuelDropL": toFixed(fuelDrop, 3)
        }
    };
}
